 "dwec-tarea2": "{\"ap1\":\"        console.log(\\\"UT02 - EJERCICIO 1\\\");       \\n        const tabla7 = 7;\\n        const tabla8 = 8;\\n        const tabla9 = 9;\\n\\n        console.log(\\\"Tabla de multiplicar del 7:\\\");\\n        for (let i = 1; i <= 10; i++) {\\n            console.log(tabla7 + \\\" x \\\" + i + \\\" = \\\" + (tabla7 * i));\\n        }\\n        console.log(\\\"Tabla de sumar del 8:\\\");\\n        let i = 1;\\n        while (i <= 10) {\\n            console.log(tabla8 + \\\" + \\\" + i + \\\" = \\\" + (tabla8 + i));\\n            i++;\\n        }\\n        console.log(\\\"Tabla de dividir del 9:\\\");\\n        let j = 1;\\n        do {    \\n            console.log(tabla9 + \\\" / \\\" + j + \\\" = \\\" + (tabla9 / j));\\n            j++;\\n        } while (j <= 10);\",\"ap2\":\"        console.log(\\\"UT02 - EJERCICIO 2\\\");\\n        console.log(125 + \\\" / 8 = \\\" + (125 >> 3));\\n        console.log(40 + \\\" x 4 = \\\" + (40 << 2));\\n        console.log(25 + \\\" / 2 = \\\" + (25 >> 1));\\n        console.log(10 + \\\" x 16 = \\\" + (10 << 4));\",\"com\":\" \"}",
